@pytest.mark.parametrize('dim', [0, 1]) def test_finite_endpoint_parallel_transport_is_tangent_isometric_and_reversible(dim): torch.manual_seed(37) old = normalized((7, 5), dim) raw_a, raw_b = torch.randn_like(old), torch.randn_like(old) tangent = compiled(lambda p, v: trial.tangent_projection(p, v, dim)) transport = compiled(lambda p, q, v: trial.sphere_parallel_transport(p, q, v, dim)) a, b = tangent(old, raw_a), tangent(old, raw_b) # A real finite retraction, sufficiently far from old for projection alone # to lose norm, but in the non-antipodal hemisphere. new = torch.nn.functional.normalize(old + .7*a, dim=dim) saved_old, saved_new, saved_a = old.clone(), new.clone(), a.clone() ta, tb = transport(old, new, a), transport(old, new, b) torch.testing.assert_close((ta*new).sum(dim), torch.zeros_like((ta*new).sum(dim)), atol=8e-7, rtol=0) torch.testing.assert_close(ta.square().sum(dim), a.square().sum(dim), atol=3e-6, rtol=2e-6) torch.testing.assert_close((ta*tb).sum(dim), (a*b).sum(dim), atol=3e-6, rtol=2e-6) torch.testing.assert_close(transport(new, old, ta), a, atol=2e-6, rtol=2e-6) > assert float((trial.tangent_projection(new, a).square().sum(dim)-a.square().sum(dim)).abs().max()) > .01 E TypeError: tangent_projection() missing 1 required positional argument: 'dim'
